import java.util.*;

class Solution {
    public int search(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;      // avoids overflow of (lo + hi)
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) lo = mid + 1; // target must be on the right
            else hi = mid - 1;                     // target must be on the left
        }
        return -1;                                 // window became empty
    }
}

